🐛 Describe the bug
I came across a performance issue that I managed to reduce into a MRE.
I want to initialize a tensor and then fill each row (each input) in the batch. So naturally I just did tensor[i] and passed that to my function. Say my function is void fill_nn_input(float* tensor_data). Consider these two ways:

fill_nn_input((float*)input[i].mutable_data_ptr());
fill_nn_input((float*)input.mutable_data_ptr() + i * row_stride);

My understanding is that torch::Tensor is some kind of wrapper around the data in the device, and indexing just gives you another wrapper pointing to the same data but with offsets changed, so basically free. For some reason, the first one is 40 times slower than the second in my tests. Both with CUDA and CPU, seems like a frontend issue.
This is the MRE I came up with:
#include <iostream>
#include <chrono>

#include <torch/torch.h>

void fill_nn_input(float* tensor_data) {
    // would fill 222 items
    tensor_data[0] = 1;
    tensor_data[1] = 2;
    tensor_data[2] = 3;
}

int main() {
    std::string model_path = "./test_net.pt";

    constexpr bool use_slow_indexing = false;
    const auto device = torch::kCUDA;
    const int N = 4096;

    auto model = torch::jit::load(model_path, device);
    model.to(device);
    model.eval();

    torch::NoGradGuard no_grad;

    for (int repeats = 0; repeats < 10; repeats++) {
        auto start = std::chrono::high_resolution_clock::now();

        for (int i = 0; i < 100; i++) {
            auto input = torch::zeros({ N, 222 }, torch::kFloat32);

            // fill inputs
            for (int i = 0; i < N; i++) {
                if (use_slow_indexing) {
                    fill_nn_input((float*)input[i].mutable_data_ptr());
                }
                else {
                    fill_nn_input((float*)input.mutable_data_ptr() + i * 222);
                }
            }

            // Check to see if addresses match
            // float* a = (float*)input[i].mutable_data_ptr();
            // float* b = (float*)input.mutable_data_ptr() + i * 222;
            // std::cout << a << " == " << b << std::endl;

            // inference
            auto outputs = model.forward({ input.to(device) });
        }

        auto end = std::chrono::high_resolution_clock::now();
        auto duration = std::chrono::duration_cast<std::chrono::milliseconds>(end - start);
        std::cout << "Time taken: " << duration.count() << " milliseconds" << std::endl;
    }
}

To switch between the two, change the use_slow_indexing flag. I can share my CMakeLists.txt if necessary.

Network used to test
import torch
import torch.nn as nn

class TestNet(nn.Module):
    def __init__(self):
        super(TestNet, self).__init__()
        self.num_inputs = 200 + 22
        self.num_outputs = 5

        self.seq = nn.Sequential(
            nn.Linear(self.num_inputs, 32),
            nn.ReLU(),
            nn.Linear(32, 32),
            nn.ReLU(),
            nn.Linear(32, self.num_outputs),
        )

        self.softmax = nn.Softmax(dim=1)

    def forward(self, x):
        x = self.seq(x)
        return self.softmax(x)

script_model = torch.jit.script(TestNet())
script_model.save("test_net.pt")

