🐛 Describe the bug
Here is the minimal reproducer. inductor generates wrong cpp code on cpu that leads to corrupted memory.
import numpy
import torch
from torch import Tensor


def func(
    xs: Tensor,
    Ls: Tensor,
):
    arr = -torch.einsum("i...,i->i...", xs, Ls)
    temp = torch.exp(arr)
    Q = torch.einsum("i...->i", temp)
    ans = torch.einsum("i,i...->i...", 1 / Q, temp)

    return ans


func = torch.compile(func, backend="inductor")

xs = torch.ones((5, 1, 32, 32), requires_grad=False)
Ls = torch.ones((5), requires_grad=False)

func(xs, Ls)
